#!/usr/bin/env python3
"""Emit docs/inventory.md (markdown tables) + data/inventory.csv from data/facilities.js."""
import json, os, csv
H = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
txt = open(os.path.join(H, 'data/facilities.js')).read()
D = json.loads(txt[txt.index('{'):txt.rindex('}') + 1])
zn = {z['id']: z['name'] for z in D['zones']}
L = ['# Facility inventory (generated by tools/make_inventory.py)\n',
     'Flows: 2025 Operations Summary Report App. C. Wells/treatment/volumes: 2025 Annual Water Quality Report. `loc` = real (Kitchener GIS/OSM) or est (approximate). Zone = training aggregation (estimate).\n',
     '## Supply sites\n', '| ID | Site | Type | Wells | Treatment | Clearwell m³ | HL pumps | MDWL m³/d | 2025 avg m³/d | 2025 max day m³/d | Peak raw L/s | Zone | Lat, Lon | loc |', '|' + '---|' * 14]
rows = []
for s in D['sites']:
    tr = ', '.join([x for x in [s['greensand'] and 'greensand', s['aop'] and 'AOP', s['gac'] and 'GAC', s['uv'] and 'UV'] if x] + s['chem'])
    L.append(f"| {s['id']} | {s['name']} | {s['kind']} | {' '.join(s['wells'])} | {tr} | {s['clearwellM3'] or ''} | {s['highLiftPumps'] or ''} | {s['mdwlM3d']:,.0f} | {s['avg2025M3d']:,.0f} | {s['maxDay2025M3d']:,.0f} | {s['peakRawLs2025']:.1f} | {s['zone']} | {s['lat']:.4f}, {s['lon']:.4f} | {s['locQuality']} |")
    rows.append([s['id'], s['name'], s['kind'], ' '.join(s['wells']), tr, s['clearwellM3'], s['highLiftPumps'], s['mdwlM3d'], s['avg2025M3d'], s['maxDay2025M3d'], s['peakRawLs2025'], s['zone'], s['lat'], s['lon'], s['locQuality'], s['standbyPower']])
L += ['\n## Storage / towers / intake\n', '| ID | Name | Type | Volume m³ | Volume est? | Zone | Lat, Lon | loc |', '|' + '---|' * 8]
for t in D['storage']:
    L.append(f"| {t['id']} | {t['name']} | {t['type']} | {t['volM3'] or ''} | {'est' if t['volEst'] else 'AWQR'} | {t['zone']} | {t['lat']:.4f}, {t['lon']:.4f} | {t['locQuality']} |")
L += ['\n## Training zones\n', '| ID | Name | Storage | m³ | Demand (2025 avg of sources) m³/d | Sites |', '|---|---|---|---|---|---|']
for z in D['zones']:
    L.append(f"| {z['id']} | {z['name']} | {z['storageName']} | {z['storageM3']:,} | {z['avgDemandM3d']:,} | {' '.join(z['sites'])} |")
L += ['\n## Grand River near Doon (02GA048) monthly flow 2015–2025 (m³/s)\n', '| Month | P10 | Median | P90 |', '|---|---|---|---|']
for m, v in D['grandRiverMonthly'].items(): L.append(f"| {m} | {v['p10']} | {v['median']} | {v['p90']} |")
open(os.path.join(H, 'docs/inventory.md'), 'w').write('\n'.join(L) + '\n')
with open(os.path.join(H, 'data/inventory.csv'), 'w', newline='') as f:
    w = csv.writer(f); w.writerow(['id', 'name', 'kind', 'wells', 'treatment', 'clearwell_m3', 'highlift_pumps', 'mdwl_m3d', 'avg2025_m3d', 'maxday2025_m3d', 'peak_raw_Ls_2025', 'training_zone', 'lat', 'lon', 'loc_quality', 'standby_power']); w.writerows(rows)
print('sites', len(D['sites']), 'wells', sum(len(s['wells']) for s in D['sites']), 'real loc', sum(s['locQuality'] == 'real' for s in D['sites']))
